var objs = [];
var objsNum = 300;
var palette = ["#FFFF00", "#00FFFF", "#FF00FF"];

var pg;
var yoff = 0.0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES);
	noStroke();

	for (i = 0; i < objsNum; i++) {
		objs.push(new Obj());
	}

	bg = color(0);

	pg = createGraphics(width, height);
	pg.background(0);
}

function draw() {
	background(0);

	for (i = 0; i < objsNum; i++) {
		objs[i].move();
		objs[i].display();
	}

	pg.background(0, 20);

	pg.noFill();

	pg.erase();
	for (j = 0; j < 5; j++) {
		pg.strokeWeight(j * 2 + 1);

		pg.beginShape();
		for (x = 0; x < width; x++) {
			let y = noise(x * 0.004, j* 0.3 + yoff) * height;
			pg.vertex(x, y);
		}
		pg.endShape();
	}
	pg.noErase();

	yoff += 0.01;

	image(pg, 0, 0);
}

class Obj {
	constructor() {
		this.vertexNum = floor(random(3, 7));
		this.r = [];
		for (i = 0; i < this.vertexNum; i++) {
			this.r.push(random(10, 100));
		}
		this.maxR = max(this.r);
		this.c = random(palette);
		this.speed = random(2, 6);

		this.x = random(width);
		this.y = random(-this.maxR, height + this.maxR);

		this.t = random(360);
		this.tStep = random(-3, 3);
	}

	move() {
		this.t += this.tStep;

		this.y += this.speed;
		if (this.y > height + this.maxR) {
			this.x = random(width);
			this.c = random(palette);
			this.speed = random(2, 6);
			this.tStep = random(-3, 3);
			this.y = -this.maxR;
		}
	}

	display() {
		fill(this.c);
		push();
		translate(this.x, this.y);
		rotate(this.t);
		beginShape();
		for (i = 0; i < this.vertexNum; i++) {
			vertex(this.r[i] * cos(360 * i / this.vertexNum),
				this.r[i] * sin(360 * i / this.vertexNum));
		}
		endShape(CLOSE);
		pop();
	}
}
